function UISweepPrepareDialog:CleanProperties()
    self.questId = nil
    self.curSweepTimes = nil
end

function UISweepPrepareDialog:InitComponent()
    self.curSweepTimes = InitSweepTimes
    self.questType = GoodsUtils.GetIdType(self.questId, Constants.IDArea.Quests)
    self.questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.questId)
    self.costId = checkNumber(self.questVo.costItem)
    self.costNum = checkNumber(self.questVo.costNum) + checkNumber(self.questVo.costNumLose) --策划要求修改为只读costNum
    -- 计算天赋加成
    self.costNum = GameUtils.CalculateCostNumWithTalentAddition(self.questVo, self.costNum)

    self:RefreshCostItemGroup()

    SetButtonAction(self.RT_BtnClose.gameObject, Bind(self, self.OnCloseBtnClicked))
    SetButtonAction(self.Btn_Add.gameObject, Bind(self, self.OnAddBtnClicked))
    SetButtonAction(self.Btn_AddMulti.gameObject, Bind(self, self.OnMultiAddBtnClicked))
    SetButtonAction(self.Btn_Sub.gameObject, Bind(self, self.OnSubBtnClicked))
    SetButtonAction(self.Btn_SubMulti.gameObject, Bind(self, self.OnMultiSubBtnClicked))
    SetButtonAction(self.Btn_Sweep.gameObject, Bind(self, self.OnSweepBtnClicked))
    self.InputField_SweepTimes.onEndEdit:AddListener(Bind(self, self.SetSweepTimes))
end

--- 刷新显示消耗材料
function UISweepPrepareDialog:RefreshCostItemGroup()
    local data = {}
    -- 消耗材料
    local times = 0
    local perCostNum = 0
    if checkNumber(self.questVo.levelType) == Constants.RegionSecondQuestType.Equip then
        ---装备本
        --@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
        times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
        if status == 1 and times > 0  then
            ---@type TableML.TableFile
            local tableFile = settingModule.Get(AutoIds.IdSetting313)
            ---@type TableML.TableFileRow
            local row = tableFile:GetByPrimaryKey(checkNumber(self.questId), false)
            if row then
                perCostNum = checkNumber(row:Get("costNum")) + checkNumber(self.questVo.costNumLose)
            end
        end
    end
    if times > 0 then
        ---存在装备消耗的选取
        local num = 0
        if self.curSweepTimes <= times then
            num = perCostNum * self.curSweepTimes
        else
            num = self.costNum * (self.curSweepTimes - times) + perCostNum * times
        end
        table.insert(data, {goodsId = self.costId, num = num })
    else
        table.insert(data, {goodsId = self.costId, num = self.costNum * self.curSweepTimes })
    end
    local needSweepTicket = true
    if needSweepTicket then
        -- 扫荡券
        table.insert(data, {goodsId = SweepTicketId, num = SweepTicketConsumeNum * self.curSweepTimes })
    end

    -- 刷新显示
    if isNull(self.LB_CostItemGroup.Env) then
        self.LB_CostItemGroup:Init()
    end
    ---@type CommonGoodsList
    local LT_CostItemGroup = self.LB_CostItemGroup.Env
    LT_CostItemGroup:FreshBaseUI(data)
end

--- 增加扫荡次数
---@param times any
function UISweepPrepareDialog:AddSweepTimes(times)
    times = checkInt(times)
    self.curSweepTimes = self.curSweepTimes + times
    self.curSweepTimes = Mathf.Clamp(self.curSweepTimes, SweepTimesMin, self:GetSweepTimesMax())
    self:RefreshCostItemGroup()
    self.InputField_SweepTimes.text = tostring(self.curSweepTimes)
end

--- 设置扫荡次数
---@param times any
function UISweepPrepareDialog:SetSweepTimes(times)
    times = checkInt(times)
    self.curSweepTimes = times
    self.curSweepTimes = Mathf.Clamp(self.curSweepTimes, SweepTimesMin, self:GetSweepTimesMax())
    self:RefreshCostItemGroup()
    self.InputField_SweepTimes.text = tostring(self.curSweepTimes)
end

