function UISweepPrepareDialog:OnSweepBtnClicked()
    local rewardVo = RewardConfMgr:GetInstance():GetQuestRewardVo(self.questId)
    -- if isNotNull(rewardVo) and isNotNull(rewardVo.GetRewards) then
    --     local rewards = rewardVo:GetRewards()
    --     -- print("[扫荡] ", self.questId, table.dump(rewards, nil, 3))
    --     local isFilled, packetVo = GoodsUtils.IsGoodsPacketFull(rewards)
    --     if isFilled then
    --         GameUtils.Toast(localize("_name_背包已满，请前往清理", {_name_ = packetVo.name}))
    --         return
    --     end
    -- else
    --     if Application.isEditor then
    --         printError("没有找到关卡奖励，请添加获取逻辑")
    --     end
    --     local isFilled, packetVo = GoodsUtils.IsPacketFilled()
    --     if isFilled then
    --         GameUtils.Toast(localize("_name_背包已满，请前往清理", {_name_ = packetVo.name}))
    --         return
    --     end
    -- end
    
    -- 选择接口
    local interface = ""
    if isNotNull(self.interface) then
        interface = self.interface
    else
        if self.questType == Constants.IDType.QuestDaily then
            interface = Interfaces.OverseaRegionalDailySweep    -- 日常副本奖励表
        elseif self.questType == Constants.IDType.QuestRegion then
            interface = Interfaces.OverseaRegionalSweep
        elseif self.questType == Constants.IDType.QuestMidFestivalRecord then
            interface = Interfaces.OverseaMidFestivalSweep  -- 双旦复刷奖励表
        elseif self.questType == Constants.IDType.QuestMainChallenge then
            interface = Interfaces.mainQuestDifficultSweep  -- 主线困难关卡奖励表
        elseif self.questType == Constants.IDType.QuestMapDecryptionTracking then
            interface = Interfaces.ActivityMapDecryptionChallengeSweeping   -- 追踪关卡奖励表
        end
    end
    
    -- 请求扫荡结果
    local succeed = false
    local operation = GameUtils.Request(interface, {questId = self.questId, times = self.curSweepTimes, activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if checkNumber(response.errCode) == CodeLackHP then
                -- 体力跳转
                UIModule.OpenDialog({ id = Constants.UITypeIds.UIHPDialog })
            elseif checkNumber(response.errCode) == CodeLackTicket then
                -- 扫荡券跳转
                GoodsUtils.ShowCommonLackMaterialDialog({{ goodsId = SweepTicketId, num = SweepTicketConsumeNum }})
            elseif checkNumber(response.errCode) == CodeLackSpecialTicket then
                -- 特殊券跳转
                UIModule.OpenDialog({ id = Constants.UITypeIds.StoreDiamondExchangeDialog,
                                      parameters = {id = Constants.Currency.SPTicketExchangeId, callback = Bind(self, self.Refresh)}})
            elseif checkNumber(response.errCode) == CodeLackDoubleDanHP then
                ---@type ActivityMidFestivalComponent
                local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
                comp:BuyActivityHp()
            else
                GameUtils.Toast(response.errMsg)
            end
            return
        end
        succeed = true
        local jsonData = response.data
        local hp = checkNumber(jsonData.hp)
        
        local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        local entryId = midFestivalComponent:GetActivityEnergyId()
        if checkNumber(self.hpId) == entryId then
            hp = checkNumber(jsonData.doubleDanHp)
        end
        local rewards = jsonData.rewards
        local extraRewards = jsonData.extraRewards
        local playerLv = jsonData.playerLv
        local mainExp = jsonData.mainExp
        local cardExp = jsonData.cardExp
        local energyPoint = jsonData.energyPoint
        local taskInfo = jsonData.questGradeTaskProgress
        local regionalBossData = jsonData.regionalBossData

        -- print("[扫荡] response", table.dump(jsonData, nil, 5))

        local Mgr = FightPreWarMgr:GetInstance()
        local params = {}
        params.questId = self.questId
        params.questGradeTaskProgress = jsonData.questGradeTaskProgress

        -- 更新能量点儿
        if not isNull(energyPoint) then
            local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
            comp:UpdateNewDailyQuestID(self.questId, energyPoint)  -- 更新最近关卡
        end
        if isSet(jsonData, "consumeActivityResidueNum") then
            --@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
            if status == 1 then
                playerComponent.playerDojo.consumeCopyActivity.residueNum = checkNumber(jsonData.consumeActivityResidueNum)
                Events.Broadcast("CONSUME_EQUIP_ACTIVITY_NUM")
            end
            xTry(function()
                self:RefreshCostItemGroup()
            end)
        end
        -- 更新玩家经验
        local playerOldLv, playerOldExp = Mgr:UpdatePlayerExp(jsonData)
        params.playerExpInfo = {
            newLv = jsonData.playerLv,
            oldLv = playerOldLv,
            newExp = jsonData.mainExp,
            oldExp = playerOldExp,
        }
        -- 更新卡牌经验
        params.cardExpInfo = Mgr:UpdateCardExp(jsonData)
        
        -- 更新玩家奖励
        for k, rewards in pairs(jsonData.rewards) do
            GoodsUtils.DrawRewards(rewards, false)
        end

        -- 特殊材料副本，消耗特殊券
        if self.costId == ActionUtils.GetDailyQuestTicketId() then
            local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
            comp:ConsumeTicket(self.curSweepTimes)
        elseif self.questType == Constants.IDType.QuestMainChallenge then
            ---@type QuestComponent
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
            comp:UpdateChallengePassedTimes(self.curSweepTimes)
        end

        local costSweepTicket = true
        -- 更新扫荡券
        if costSweepTicket then
            GoodsUtils.DrawRewards({ {goodsId = SweepTicketId, num = -SweepTicketConsumeNum * self.curSweepTimes} })
        end

        -- 更新体力
        if not isNull(hp) then
            GoodsUtils.DrawRewards({{
                num = hp - GoodsUtils.GetThingNo(self.hpId),
                goodsId = self.hpId
            }}, true)
        end

        -- 传递奖励数据
        params.rewards = jsonData.rewards
        params.extraRewards = jsonData.extraRewards

        -- 记录歼灭战数据和是否触发
        if not IsNull(regionalBossData) then
            params.needShowAnnihilationPopup = Mgr:NeedShowAnnihilationPopup(self.questId, regionalBossData)
            params.regionalBossData = regionalBossData
            -- print("[扫荡] 歼灭战进度", regionalBossData.progress)
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
            comp:UpdateReginQuestInfo(self.questId, regionalBossData)
        end
        self:FreshEquipTimes()
        UIModule.OpenDialog({id = Constants.UITypeIds.UISweepResultDialog, parameters = params})

    end, nil, nil, nil, nil, true)
end

