--- 获取扫荡的最大次数
function UISweepPrepareDialog:GetSweepTimesMax()
    local max = SweepTimesMax
    if self.costId == ActionUtils.GetDailyQuestTicketId() then
        max = SPSweepTimesMax
    elseif self.questType == Constants.IDType.QuestMainChallenge then
        ---@type QuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local totalTime = comp:GetChallengeTotalTimes()
        local havePassTime = comp:GetChallengePassedTimes()
        local leaveTime = totalTime - havePassTime
        return leaveTime
    end
    return max
end

return UISweepPrepareDialog
